head.script:
// WAEA-951 : advancedExcelDownload dialogTitle 옵션이 Gear 요청 XML 에 실리는지 확인.
// Gear 는 필요 없음. core.excelDownload 를 가로채 payload 만 검사하므로 실제 다운로드는 발생하지 않음.

scwin.TITLE = "NH Gear's <Dialog> & Title\nLine2";

scwin.onpageload = function() {
    dataList1.setJSON([
        { col1: "A001", col2: "NongHyup" },
        { col1: "A002", col2: "Gear" }
    ]);
    scwin.log("WAEA-951 dialogTitle payload 검증. 버튼을 위에서부터 순서대로 누르세요.");
    scwin.log("테스트 문자열 : " + JSON.stringify(scwin.TITLE));
};

scwin.log = function(msg) {
    var t = new Date();
    var ts = ("0" + t.getHours()).slice(-2) + ":" + ("0" + t.getMinutes()).slice(-2) + ":" + ("0" + t.getSeconds()).slice(-2);
    txa_log.setValue(txa_log.getValue() + "[" + ts + "] " + msg + "\n");
};
scwin.logRaw = function(msg) {
    txa_log.setValue(txa_log.getValue() + "    " + msg + "\n");
};

// ---- payload 파싱 (따옴표 종류에 의존하지 않음) ----
scwin.hasHashkey = function(payload, hashkey) {
    return new RegExp("hashkey=['\"]" + hashkey + "['\"]").test(String(payload || ""));
};
scwin.getHashValue = function(payload, hashkey) {
    var pattern = new RegExp("hashkey=['\"]" + hashkey + "['\"][^>]*?value=(['\"])([\\s\\S]*?)\\1");
    var match = String(payload || "").match(pattern);
    return match ? match[2] : null;
};

// ---- escape 검증: 엔티티를 걷어낸 뒤 원문자가 남아있으면 escape 누락 ----
scwin.checkEscape = function(value) {
    if (value == null) { return { ok: false, detail: "값 없음" }; }
    var stripped = String(value).replace(/&(amp|lt|gt|apos|quot|#x?[0-9A-Fa-f]+);/g, "");
    var leftover = [];
    if (stripped.indexOf("'") > -1) { leftover.push("'"); }
    if (stripped.indexOf("<") > -1) { leftover.push("<"); }
    if (stripped.indexOf(">") > -1) { leftover.push(">"); }
    if (stripped.indexOf("&") > -1) { leftover.push("&"); }
    if (stripped.indexOf("\n") > -1) { leftover.push("\\n"); }
    return leftover.length
        ? { ok: false, detail: "escape 안 된 원문자: " + leftover.join(" ") }
        : { ok: true, detail: "5종 특수문자 모두 escape 됨" };
};

// ---- core.excelDownload 후킹 : 실제 전송 없이 payload 만 수집 ----
scwin.capture = function(fn) {
    var captured = null;
    var core = WebSquare.core;
    var original = core.excelDownload;
    var hooked = false;

    core.excelDownload = function(action, data) {
        hooked = true;
        captured = (data && typeof data.join === "function") ? data.join("") : String(data || "");
        return data;
    };
    try {
        fn();
    } finally {
        core.excelDownload = original;
    }
    return { hooked: hooked, payload: captured };
};

// ---- 결과 판정 및 출력 ----
scwin.report = function(label, payload, expectDialogTitle, hooked) {
    scwin.log(label);

    if (hooked === false) {
        scwin.logRaw("FAIL : core.excelDownload 을 타지 않음. 후킹 지점이 잘못됐거나 다른 다운로드 경로임.");
        scwin.logRaw("       -> 'dialogTitle 없음' 으로 해석하지 말 것.");
        return;
    }
    payload = String(payload || "");
    scwin.lastPayload = payload;
    scwin.logRaw("payloadLength = " + payload.length);
    if (payload.length === 0) {
        scwin.logRaw("FAIL : payload 가 비어 있음. 판정 불가.");
        return;
    }

    var has = scwin.hasHashkey(payload, "dialogTitle");
    var val = scwin.getHashValue(payload, "dialogTitle");
    scwin.logRaw("hasDialogTitle = " + has + "  (기대: " + expectDialogTitle + ")");

    if (has !== expectDialogTitle) {
        scwin.logRaw("판정 : FAIL");
        if (val != null) { scwin.logRaw("dialogTitleValue = " + val); }
        return;
    }
    if (!expectDialogTitle) {
        scwin.logRaw("판정 : PASS  (미설정 시 hashkey 미전송 - 하위호환 OK)");
        return;
    }

    scwin.logRaw("dialogTitleValue = " + val);
    var esc = scwin.checkEscape(val);
    scwin.logRaw("escape 검사 = " + (esc.ok ? "PASS" : "FAIL") + "  (" + esc.detail + ")");
    scwin.logRaw("판정 : " + (esc.ok ? "PASS" : "FAIL"));
};

// ---- ① GridView + dialogTitle 지정 ----
scwin.btn_grid_with_onclick = function() {
    var r = scwin.capture(function() {
        gridView1.advancedExcelDownload({
            fileName: "WAEA_951_dialogTitle.xlsx",
            extension: "xlsx",
            showProcess: false,
            useXHR: "true",
            dialogTitle: scwin.TITLE
        });
    });
    scwin.report("① GridView advancedExcelDownload + dialogTitle 지정", r.payload, true, r.hooked);
};

// ---- ② GridView + dialogTitle 미지정 (하위호환) ----
scwin.btn_grid_without_onclick = function() {
    var r = scwin.capture(function() {
        gridView1.advancedExcelDownload({
            fileName: "WAEA_951_no_dialogTitle.xlsx",
            extension: "xlsx",
            showProcess: false,
            useXHR: "true"
        });
    });
    scwin.report("② GridView advancedExcelDownload + dialogTitle 미지정", r.payload, false, r.hooked);
};

// ---- ③ GridView + dialogTitle 빈 문자열 (스펙 미정 구간) ----
scwin.btn_grid_empty_onclick = function() {
    var r = scwin.capture(function() {
        gridView1.advancedExcelDownload({
            fileName: "WAEA_951_empty_dialogTitle.xlsx",
            extension: "xlsx",
            showProcess: false,
            useXHR: "true",
            dialogTitle: ""
        });
    });
    scwin.log("③ GridView advancedExcelDownload + dialogTitle=\"\" (빈 문자열)");
    if (r.hooked === false) {
        scwin.logRaw("FAIL : core.excelDownload 을 타지 않음.");
        return;
    }
    var payload = String(r.payload || "");
    scwin.lastPayload = payload;
    var has = scwin.hasHashkey(payload, "dialogTitle");
    scwin.logRaw("payloadLength = " + payload.length);
    scwin.logRaw("hasDialogTitle = " + has);
    scwin.logRaw("dialogTitleValue = " + scwin.getHashValue(payload, "dialogTitle"));
    scwin.logRaw("※ 기대값이 스펙에 정의되어 있지 않음. 결과를 기록해 스펙 확정 필요.");
    scwin.logRaw("   (미설정과 동일하게 hashkey 미전송 / 빈 제목 전송 중 어느 쪽인지)");
};

// ---- ④ DataList (multipleDataListDownload 경로) ----
scwin.btn_datalist_onclick = function() {
    try {
        var sendArray = WebSquare.util.sendDataList(dataList1, {
            fileName: "WAEA_951_dataList_dialogTitle.xlsx",
            sheetName: "sheet1",
            dialogTitle: scwin.TITLE
        }, [], "");
        scwin.report("④ DataList sendDataList + dialogTitle 지정", sendArray.join(""), true, true);
    } catch (e) {
        scwin.log("④ DataList sendDataList + dialogTitle 지정");
        scwin.logRaw("ERROR : " + e.message);
    }
};

// ---- ⑤ multipleExcelDownload 경로 (API 시그니처 확인용 프로브) ----
scwin.btn_multiple_onclick = function() {
    scwin.log("⑤ multipleExcelDownload 경로");

    var candidates = [
        { name: "gridView1.multipleExcelDownload", fn: gridView1.multipleExcelDownload, ctx: gridView1 },
        { name: "WebSquare.util.multipleExcelDownload", fn: WebSquare.util && WebSquare.util.multipleExcelDownload, ctx: WebSquare.util },
        { name: "WebSquare.core.multipleExcelDownload", fn: WebSquare.core && WebSquare.core.multipleExcelDownload, ctx: WebSquare.core }
    ];
    var found = null;
    for (var i = 0; i < candidates.length; i++) {
        if (typeof candidates[i].fn === "function") {
            scwin.logRaw("발견 : " + candidates[i].name);
            if (!found) { found = candidates[i]; }
        }
    }
    if (!found) {
        scwin.logRaw("SKIP : multipleExcelDownload API 를 찾지 못함. 시그니처 확인 필요.");
        scwin.logRaw("       수정 범위에 포함된 경로이므로 별도 확인이 필요합니다.");
        return;
    }

    var r = scwin.capture(function() {
        found.fn.call(found.ctx, {
            fileName: "WAEA_951_multiple.xlsx",
            extension: "xlsx",
            showProcess: false,
            useXHR: "true",
            dialogTitle: scwin.TITLE
        });
    });
    if (r.hooked === false) {
        scwin.logRaw("SKIP : 호출은 됐으나 core.excelDownload 을 타지 않음. 인자 형태 확인 필요.");
        return;
    }
    scwin.report("   -> " + found.name + " payload", r.payload, true, r.hooked);
};

// ---- payload 원문 확인 ----
scwin.btn_dump_onclick = function() {
    if (!scwin.lastPayload) {
        scwin.log("먼저 ①~⑤ 중 하나를 실행하세요.");
        return;
    }
    console.log("[WAEA-951] last payload:\n" + scwin.lastPayload);
    scwin.log("마지막 payload 원문을 개발자도구 Console 에 출력했습니다. (길이 " + scwin.lastPayload.length + ")");
};

scwin.btn_clear_onclick = function() {
    txa_log.setValue("");
};
